export class HttpForgejoClient {
    http;
    owner;
    repo;
    constructor(http, owner, repo) {
        this.http = http;
        this.owner = owner;
        this.repo = repo;
    }
    path(p) {
        return `/api/v1/repos/${encodeURIComponent(this.owner)}/${encodeURIComponent(this.repo)}${p}`;
    }
    async listTags() {
        const tags = [];
        let page = 1;
        for (;;) {
            const res = await this.http.request("GET", this.path(`/tags?page=${page}&limit=50`));
            await assertOk(res, "list tags");
            const batch = (await res.json());
            if (batch.length === 0)
                break;
            for (const t of batch)
                tags.push(t.name);
            if (batch.length < 50)
                break;
            page++;
        }
        return tags;
    }
    async getLatestRelease() {
        const res = await this.http.request("GET", this.path(`/releases/latest`));
        if (res.status === 404)
            return null;
        await assertOk(res, "get latest release");
        const r = (await res.json());
        return { id: r.id, tagName: r.tag_name, targetCommitish: r.target_commitish };
    }
    async compareCommits(base, head) {
        const res = await this.http.request("GET", this.path(`/compare/${encodeURIComponent(base)}...${encodeURIComponent(head)}`));
        await assertOk(res, "compare commits");
        const data = (await res.json());
        return (data.commits ?? []).map((c) => ({ sha: c.sha, message: c.commit.message }));
    }
    async getPullRequest(number) {
        const res = await this.http.request("GET", this.path(`/pulls/${number}`));
        await assertOk(res, `get PR #${number}`);
        const pr = (await res.json());
        return {
            number: pr.number,
            title: pr.title,
            author: pr.user?.login ?? "",
            labels: pr.labels.map((l) => l.name),
            url: pr.html_url,
            mergeCommitSha: pr.merge_commit_sha ?? "",
        };
    }
    async listMergedPullRequests() {
        const out = [];
        let page = 1;
        for (;;) {
            const res = await this.http.request("GET", this.path(`/pulls?state=closed&sort=newest&page=${page}&limit=50`));
            await assertOk(res, "list pulls");
            const batch = (await res.json());
            if (batch.length === 0)
                break;
            for (const pr of batch) {
                if (!pr.merged)
                    continue;
                out.push({
                    number: pr.number,
                    title: pr.title,
                    author: pr.user?.login ?? "",
                    labels: pr.labels.map((l) => l.name),
                    url: pr.html_url,
                    mergeCommitSha: pr.merge_commit_sha ?? "",
                });
            }
            if (batch.length < 50)
                break;
            page++;
        }
        return out;
    }
    async createRelease(input) {
        const res = await this.http.request("POST", this.path(`/releases`), {
            tag_name: input.tagName,
            target_commitish: input.targetCommitish,
            name: input.name,
            body: input.body,
            draft: input.draft,
            prerelease: input.prerelease,
        });
        await assertOk(res, "create release");
        const r = (await res.json());
        return { id: r.id, tagName: r.tag_name, targetCommitish: r.target_commitish };
    }
}
async function assertOk(res, what) {
    if (res.ok)
        return;
    const text = await res.text().catch(() => "");
    throw new Error(`Forgejo API ${what} failed: ${res.status} ${res.statusText} ${text}`);
}
export class FetchHttp {
    baseUrl;
    token;
    constructor(baseUrl, token) {
        this.baseUrl = baseUrl;
        this.token = token;
    }
    async request(method, path, body) {
        const headers = {
            Authorization: `token ${this.token}`,
            Accept: "application/json",
        };
        if (body !== undefined)
            headers["Content-Type"] = "application/json";
        return fetch(`${this.baseUrl}${path}`, {
            method,
            headers,
            body: body === undefined ? undefined : JSON.stringify(body),
        });
    }
}
